  const D = {
    s_m20roofer: "data:image/png;base64,",
    s_m20abbot: "data:image/png;base64,",
    s_m20huntmaster: "data:image/png;base64,",
    s_m20cistern: "data:image/png;base64,",
    s_m20spire: "data:image/png;base64,",
    s_m20oathbound: "data:image/png;base64,",
    s_m20arbalest: "data:image/png;base64,",
    s_m20crow: "data:image/png;base64,",
    s_m20wight: "data:image/png;base64,",
    s_m20drowned: "data:image/png;base64,",
    ic_m20censer: "data:image/png;base64,",
    ic_m20trident: "data:image/png;base64,",
    ic_m20halberd: "data:image/png;base64,",
    ic_m20seal: "data:image/png;base64,",
    ic_m20lantern: "data:image/png;base64,"
  };
  for (const k in D) window.ASSETS[k] = D[k];
